:root {
  --bg-color: #0f172a;
  --card-bg: rgba(30, 41, 59, 0.7);
  --accent: #38bdf8;
  --text: #f8fafc;
  --radius: 12px;
}
body {
  background: var(--bg-color);
  color: var(--text);
  font-family: system-ui, sans-serif;
  margin: 0;
  padding: 20px;
}
.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}
.sensor-card {
  background: var(--card-bg);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius);
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.sensor-card:hover {
  transform: translateY(-4px);
  border-color: var(--accent);
}
@media (max-width: 600px) {
  body { padding: 10px; }
}

// DOM Elemanlarını Seçme
const sensorBtn = document.querySelector('#sensor-read');
const sensorOut = document.querySelector('#sensor-value');
const ledBtn = document.querySelector('#led-toggle');
const ledState = document.querySelector('#led-state');
const ledIndicator = document.querySelector('#led');

// Sensör Simülasyonu (20 - 30 °C aralığında rastgele değer)
sensorBtn?.addEventListener('click', () => {
  const randomTemp = (20 + Math.random() * 10).toFixed(1);
  sensorOut.textContent = `${randomTemp} °C (Canlı Ölçüm)`;
});

// Sanal LED / Röle Durum Kontrolü
ledBtn?.addEventListener('click', () => {
  const isPressed = ledBtn.getAttribute('aria-pressed') === 'true';
  const nextState = !isPressed;
  ledBtn.setAttribute('aria-pressed', String(nextState));
  ledIndicator?.classList.toggle('on', nextState);
  ledState.textContent = nextState ? 'LED Aktif (Açık)' : 'LED Pasif (Kapalı)';
  console.log(`Donanım durumu güncellendi: ${nextState ? 'HIGH' : 'LOW'}`);
});

// Google Apps Script (GAS) - IoT Sensör Telemetrisi Webhook'u
// Google E-Tablo -> Uzantılar -> Apps Script alanına yapıştırıp 'Web Uygulaması' olarak dağıtın.

function doPost(e) {
  try {
    // 1. Gelen JSON verisini ayrıştır
    const data = JSON.parse(e.postData.contents);
    const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

    // 2. Zaman damgası ve sensör değerlerini hazırla
    const timestamp = new Date();
    const sensorName = data.sensor || 'LM35_Sicaklik';
    const voltage = parseFloat(data.voltage) || 0.0;
    const current = parseFloat(data.current) || 0.0;
    const power = (voltage * current).toFixed(2);

    // 3. Tabloya yeni satır olarak ekle
    sheet.appendRow([timestamp, sensorName, voltage, current, power]);

    // 4. İstemciye (ESP32) başarılı JSON yanıtı dön
    return ContentService.createTextOutput(JSON.stringify({
      status: 'SUCCESS',
      message: 'Ölçüm Google Drive tablosuna kaydedildi.',
      receivedAt: timestamp
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'ERROR',
      message: error.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}
